from hypothesis import strategies as st
import itertools


@st.composite
def gen(draw):
    T = draw(st.integers(1, 3))
    lines = [str(T)]
    for _ in range(T):
        n = draw(st.integers(1, 6))
        k = draw(st.integers(1, n))
        vals_max = draw(st.sampled_from([3, 10, 1000000]))
        mode = draw(st.integers(0, 3))
        if mode == 0:
            a = draw(st.lists(st.integers(1, vals_max), min_size=n, max_size=n))
            b = draw(st.lists(st.integers(1, vals_max), min_size=n, max_size=n))
        elif mode == 1:
            v = draw(st.integers(1, vals_max))
            a = [v] * n
            b = [v] * n
        elif mode == 2:
            a = sorted(draw(st.lists(st.integers(1, vals_max), min_size=n, max_size=n)))
            b = sorted(draw(st.lists(st.integers(1, vals_max), min_size=n, max_size=n)), reverse=True)
        else:
            a = [1] * n
            b = [1000000] * n
            if draw(st.booleans()):
                a = [1000000] * n
                b = [1] * n
        lines.append(f"{n} {k}")
        lines.append(" ".join(map(str, a)))
        lines.append(" ".join(map(str, b)))
    return "\n".join(lines) + "\n"


def _parse(inp):
    t = inp.split()
    pos = 0

    def nxt():
        nonlocal pos
        if pos >= len(t):
            raise ValueError
        x = int(t[pos])
        pos += 1
        return x

    T = nxt()
    if not (1 <= T <= 2 * 10**5):
        raise ValueError
    cases = []
    total_n = 0
    for _ in range(T):
        n = nxt()
        k = nxt()
        if not (1 <= n <= 2 * 10**5 and 1 <= k <= n):
            raise ValueError
        total_n += n
        A = [nxt() for _ in range(n)]
        B = [nxt() for _ in range(n)]
        for x in A + B:
            if not (1 <= x <= 10**6):
                raise ValueError
        cases.append((n, k, A, B))
    if total_n > 2 * 10**5:
        raise ValueError
    if pos != len(t):
        raise ValueError
    return cases


def validate(inp: str) -> bool:
    try:
        _parse(inp)
        return True
    except Exception:
        return False


def ref(inp: str) -> str:
    cases = _parse(inp)
    out = []
    for n, k, A, B in cases:
        best = None
        for comb in itertools.combinations(range(n), k):
            m = max(A[i] for i in comb)
            s = sum(B[i] for i in comb)
            val = m * s
            if best is None or val < best:
                best = val
        out.append(str(best))
    return "\n".join(out)
